return $input.all().map(item => {
  const numpages = item.json.numpages;
  const Title = item.json.info.Title;
  const Path = $('Webhook - Receive PDF').first().json.body.pdfPath;

  const Text = item.json.text
    ?.replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    Title: Title || 'Sin título',
    Path: Path,
    numpages: numpages,
    Text: Text
  };
});

const text = $json["Text"] || "";
const chunkSize = 2000;
const overlap = 200;
const title = $json.Title;

let chunks = [];

for (let i = 0; i < text.length; i += (chunkSize - overlap)) {
  let chunk = text.slice(i, i + chunkSize);

  if (i === 0) {
    chunk = `Title: ${title}\n\n${chunk}`;
  }

  chunks.push({ 
    chunk: chunk,
    chunkIndex: chunks.length,
    totalChunks: Math.ceil(text.length / (chunkSize - overlap))
  });
}

return chunks.map(c => ({ json: c }));

// Guardar el resultado del chunk procesado
const chunkResult = $json.output;
const chunkIndex = $('Loop Over Chunks').item.json.chunkIndex;

// Obtener resultados previos o inicializar
let allResults = $('Loop Over Chunks').context?.summaries || [];

allResults.push({
  index: chunkIndex,
  summary: chunkResult
});

// Guardar en contexto
$('Loop Over Chunks').context = { summaries: allResults };

return [{ json: { processed: true, chunkIndex: chunkIndex } }];

// Consolidar todos los resúmenes
const allSummaries = $('Loop Over Chunks').context?.summaries || [];

// Ordenar por índice
allSummaries.sort((a, b) => a.index - b.index);

// Crear texto final
const merged = allSummaries.map((item, idx) => 
  `Resumen ${idx + 1}: ${item.summary}`
).join("\n\n");

const title = $('Clean Data').first().json.Title;
const customPath = $('Clean Data').first().json.Path;
const numPages = $('Clean Data').first().json.numpages;

return [{
  json: {
    Title: title,
    CustomPath: customPath,
    numPage: numPages,
    mergedSummaries: merged
  }
}];

const customPath = $('Consolidate Summaries').first().json.CustomPath;
const summaries = $json.output;
const title = $('Consolidate Summaries').first().json.Title;
const numpage = $('Consolidate Summaries').first().json.numPage;

const cleanTitle = title?.replace(/\s+/g, '_');
const numPageText = `numero de paginas: ${numpage}`;
const mergedText = `${customPath}\n\n${summaries}\n\n${numPageText}`;

return [{
  json: {
    fileText: mergedText,
    fileTitle: cleanTitle,
    originalPath: customPath
  }
}];

// Respuesta del webhook
return [{
  json: {
    status: 'success',
    title: $('Prepare Output').first().json.fileTitle,
    path: $('Prepare Output').first().json.originalPath,
    numpages: $('Consolidate Summaries').first().json.numPage,
    savedFile: `/demo-data/${$('Prepare Output').first().json.fileTitle}.json`,
    processedAt: new Date().toISOString()
  }
}];
